Python, table-driven:

```python
from enum import Enum


class OrderState(Enum):
    CREATED = "created"
    PAID = "paid"
    SHIPPED = "shipped"
    DELIVERED = "delivered"
    CANCELLED = "cancelled"
    REFUNDED = "refunded"


TRANSITIONS: dict[OrderState, frozenset[OrderState]] = {
    OrderState.CREATED:   frozenset({OrderState.PAID, OrderState.CANCELLED}),
    OrderState.PAID:      frozenset({OrderState.SHIPPED, OrderState.REFUNDED}),
    OrderState.SHIPPED:   frozenset({OrderState.DELIVERED}),
    OrderState.DELIVERED: frozenset({OrderState.REFUNDED}),
    OrderState.CANCELLED: frozenset(),
    OrderState.REFUNDED:  frozenset(),
}


class InvalidTransition(Exception):
    def __init__(self, current: OrderState, target: OrderState):
        super().__init__(f"Cannot transition from {current.value} to {target.value}")
        self.current, self.target = current, target


class Order:
    def __init__(self, order_id: str):
        self.id = order_id
        self.state = OrderState.CREATED
        self.history: list[OrderState] = [self.state]

    def can_transition(self, target: OrderState) -> bool:
        return target in TRANSITIONS[self.state]

    def transition(self, target: OrderState) -> None:
        if not self.can_transition(target):
            raise InvalidTransition(self.state, target)
        self.state = target
        self.history.append(target)

    def pay(self):     self.transition(OrderState.PAID)
    def ship(self):    self.transition(OrderState.SHIPPED)
    def deliver(self): self.transition(OrderState.DELIVERED)
    def cancel(self):  self.transition(OrderState.CANCELLED)
    def refund(self):  self.transition(OrderState.REFUNDED)


if __name__ == "__main__":
    o = Order("A1")
    o.pay(); o.ship(); o.deliver(); o.refund()
    print([s.value for s in o.history])  # created → paid → shipped → delivered → refunded

    try:
        Order("A2").ship()
    except InvalidTransition as e:
        print(e)  # Cannot transition from created to shipped
```

Policy assumptions: cancel only before payment (paid → refund instead); no refund while shipped (wait for delivery); cancelled/refunded terminal. Change by editing `TRANSITIONS`.
Persisted orders: enforce atomically in DB, e.g. `UPDATE orders SET state=:to WHERE id=:id AND state=:from`, check rowcount → no race between concurrent transitions.
